-- 02_ddl_targets.sql  (Snowflake, v2)
-- Reference dimensions, per-country target template, routing index, history,
-- derived-column watermark, identity candidates, redemption fact.
--
-- Reference data (countries, aliases, source formats, domains) is NOT seeded here:
-- the runner seeds it from src/skypoints/config.py so Python and SQL share ONE
-- definition. The MEMBER_ALL view and the other per-country tables are also
-- generated by the runner from DIM_COUNTRY, so adding a country is one config line.
USE SCHEMA SKYPOINTS.CORE;

-- ---------------------------------------------------------------------------
-- Reference dimensions (seeded from config.py by the runner)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS DIM_COUNTRY (
    country_code  VARCHAR(3)   NOT NULL,   -- ISO alpha-3
    target_table  VARCHAR(100) NOT NULL    -- e.g. MEMBER_IND
);

CREATE TABLE IF NOT EXISTS DIM_COUNTRY_ALIAS (
    alias         VARCHAR(10) NOT NULL,    -- as seen in source data
    country_code  VARCHAR(3)  NOT NULL
);

-- One row per source system: its fixed country (per-country files) and the
-- date format of each date column (see normalize.parse_date for format names).
CREATE TABLE IF NOT EXISTS DIM_SOURCE (
    source_system  VARCHAR(10) NOT NULL,
    fixed_country  VARCHAR(3),             -- NULL when the file carries a Country column
    enroll_fmt     VARCHAR(20) NOT NULL,
    flight_fmt     VARCHAR(20) NOT NULL,
    dob_fmt        VARCHAR(20) NOT NULL,
    feed_mode      VARCHAR(10) NOT NULL    -- 'delta' | 'snapshot' (see weakness #2 fix)
);

-- Allowed values (TIER, ACTIVE, REDEMPTION_STATUS)
CREATE TABLE IF NOT EXISTS DIM_DOMAIN (
    domain  VARCHAR(30) NOT NULL,
    value   VARCHAR(50) NOT NULL
);

-- ---------------------------------------------------------------------------
-- Per-country target table template (MEMBER_IND). Every other country table is
-- created by the runner with CREATE TABLE ... LIKE MEMBER_IND.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS MEMBER_IND (
    member_key        VARCHAR(300)  NOT NULL,
    source_system     VARCHAR(10)   NOT NULL,
    source_member_id  VARCHAR(200)  NOT NULL,
    member_name       VARCHAR(2000) NOT NULL,
    enrollment_date   DATE,
    last_flight_date  DATE,
    tier_code         VARCHAR(100),
    agent_name        VARCHAR(2000),
    state             VARCHAR(100),
    country_code      VARCHAR(3)    NOT NULL,
    post_code         NUMBER(5,0),
    dob               DATE,
    is_active         VARCHAR(100),
    member_type       VARCHAR(100),
    -- derived columns: kept fresh by the incremental refresh (11_refresh_derived.sql)
    as_of_date        DATE          NOT NULL,   -- when age/stale_member were last computed
    age               NUMBER(4,0),
    stale_member      BOOLEAN,
    -- lifecycle (weakness #2): a member absent from a full-snapshot feed is
    -- soft-deleted, never silently kept as ACTIVE and never hard-deleted.
    record_status     VARCHAR(20)   NOT NULL DEFAULT 'ACTIVE',   -- ACTIVE | MISSING_FROM_FEED
    last_seen_date    DATE,
    missing_since     DATE,
    -- lineage
    feed_date         DATE,
    source_file       VARCHAR(500),
    load_id           VARCHAR(40),
    updated_at        TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
)
CLUSTER BY (member_key);
-- Snowflake does not enforce PRIMARY KEY. Uniqueness comes from MERGE on member_key
-- and is verified after every load by 10_reconcile.sql.

-- ---------------------------------------------------------------------------
-- MEMBER_INDEX: narrow routing table, one row per member -> current country.
-- It is a derived structure, not an independent source of truth: 10_reconcile.sql
-- proves after every load that it agrees with the country tables.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS MEMBER_INDEX (
    member_key    VARCHAR(300) NOT NULL,
    source_system VARCHAR(10)  NOT NULL,
    member_id     VARCHAR(200) NOT NULL,
    country_code  VARCHAR(3)   NOT NULL,
    feed_date     DATE,
    updated_at    TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
)
CLUSTER BY (member_key);

-- ---------------------------------------------------------------------------
-- MEMBER_HISTORY (weakness #1): SCD Type 2 on the attributes that matter for
-- "what tier / where was she on date X". One current row per member
-- (is_current = TRUE, valid_to NULL); a change closes it and opens a new one.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS MEMBER_HISTORY (
    member_key    VARCHAR(300) NOT NULL,
    valid_from    DATE         NOT NULL,
    valid_to      DATE,                      -- NULL while current
    is_current    BOOLEAN      NOT NULL,
    country_code  VARCHAR(3),
    tier_code     VARCHAR(100),
    is_active     VARCHAR(100),
    state         VARCHAR(100),
    load_id       VARCHAR(40),
    created_at    TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
)
CLUSTER BY (member_key);

-- Country moves are derived from history, so they can never disagree with it.
CREATE OR REPLACE VIEW V_MEMBER_MOVES AS
SELECT member_key, prev_country AS from_country, country_code AS to_country, valid_from AS moved_on
FROM (
    SELECT h.member_key, h.country_code, h.valid_from,
           LAG(h.country_code) OVER (
               PARTITION BY h.member_key
               ORDER BY h.valid_from, COALESCE(h.valid_to, DATE '9999-12-31')
           ) AS prev_country
    FROM MEMBER_HISTORY h
)
WHERE prev_country IS NOT NULL AND prev_country <> country_code;

-- ---------------------------------------------------------------------------
-- DERIVED_WATERMARK (weakness #4): the date through which age / stale_member
-- are known to be correct in every country table.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS DERIVED_WATERMARK (
    id         NUMBER(1,0) NOT NULL,         -- always 1
    as_of      DATE        NOT NULL,
    updated_at TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- ---------------------------------------------------------------------------
-- MEMBER_XREF (weakness #3): cross-source identity. Candidates are PROPOSED by
-- V_MEMBER_MATCH_CANDIDATES (09_identity.sql); a person confirms them here.
-- Nothing is merged automatically because a wrong merge is worse than a duplicate.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS MEMBER_XREF (
    golden_id     VARCHAR(40)  NOT NULL,
    member_key    VARCHAR(300) NOT NULL,
    status        VARCHAR(10)  NOT NULL,     -- CONFIRMED | REJECTED
    confirmed_by  VARCHAR(100),
    confirmed_at  TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- ---------------------------------------------------------------------------
-- Redemption fact (flattened from JSON). member_key is resolved at load time and
-- re-resolved on every later load for orphans (weakness #7). It is the stable
-- identity; the member's CURRENT country is looked up at read time, so a move
-- never leaves a stale country on the fact.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS REDEMPTION_FACT (
    txn_id         VARCHAR(100) NOT NULL,
    source_system  VARCHAR(10)  NOT NULL,    -- id namespace of member_id (default GLOBAL)
    member_id      VARCHAR(200) NOT NULL,
    member_key     VARCHAR(300),             -- NULL = orphan (member not known yet)
    txn_date       DATE,
    partner        VARCHAR(200),
    miles_redeemed NUMBER(12,0),
    status         VARCHAR(30),
    feed_date      DATE,
    source_file    VARCHAR(500),
    load_id        VARCHAR(40),
    updated_at     TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
)
CLUSTER BY (txn_date);
